package store

import (
	"context"
	"database/sql"
	"database/sql/driver"
	"errors"
	"fmt"
	"regexp"
	"strconv"
	"strings"
	"sync"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgconn"
	"github.com/jackc/pgx/v5/stdlib"
	"github.com/pressly/goose/v3"
	dbfiles "github.com/staqly/staqly/apps/api/db"
)

// PostgreSQL in cloud mode. The application keeps one set of queries, written for SQLite and generated by
// sqlc; this file runs them on PostgreSQL through a database/sql connector that rewrites each statement
// once (cached): placeholders (?, ?N → $N) and the few SQLite-only constructs the queries use. Every
// caller, generated or hand-written, gets the rewrite because it happens in the driver.
//
// Queries go with pgx's simple protocol: parameters are rendered as typed literals by pgx (no string
// building here), which lets PostgreSQL infer types the way SQLite does for `? IS NULL` and CAST(? AS ...).

// OpenPostgres connects to a PostgreSQL database (postgres:// URL) and applies the PostgreSQL migrations.
// It never falls back to SQLite: a missing or unreachable database is an error.
func OpenPostgres(ctx context.Context, url string) (*sql.DB, error) {
	db, err := OpenPostgresRaw(ctx, url)
	if err != nil {
		return nil, err
	}
	if err := MigratePostgres(ctx, db); err != nil {
		db.Close()
		return nil, err
	}
	return db, nil
}

// OpenPostgresRaw connects without migrating (tools and tests).
func OpenPostgresRaw(ctx context.Context, url string) (*sql.DB, error) {
	if !strings.HasPrefix(url, "postgres://") && !strings.HasPrefix(url, "postgresql://") {
		return nil, errors.New("DATABASE_URL must be a postgres:// URL")
	}
	cfg, err := pgx.ParseConfig(url)
	if err != nil {
		return nil, fmt.Errorf("DATABASE_URL: %w", err)
	}
	cfg.DefaultQueryExecMode = pgx.QueryExecModeSimpleProtocol
	db := sql.OpenDB(&pgConnector{inner: stdlib.GetConnector(*cfg)})
	db.SetMaxOpenConns(20)
	db.SetMaxIdleConns(10)
	if err := db.PingContext(ctx); err != nil {
		db.Close()
		return nil, fmt.Errorf("connect to PostgreSQL (DATABASE_URL): %w", err)
	}
	var version int
	if err := db.QueryRowContext(ctx, "SHOW server_version_num").Scan(&version); err != nil {
		db.Close()
		return nil, fmt.Errorf("PostgreSQL version: %w", err)
	}
	if version < 160000 {
		db.Close()
		return nil, fmt.Errorf("PostgreSQL 16 or newer is required (server is %d)", version)
	}
	// A search_path in the URL names the schema staqly lives in (one database, several environments or
	// test runs): create it when it does not exist yet.
	if sp := cfg.RuntimeParams["search_path"]; sp != "" {
		if !reSchemaName.MatchString(sp) {
			db.Close()
			return nil, fmt.Errorf("DATABASE_URL search_path %q: use one plain schema name", sp)
		}
		if _, err := db.ExecContext(ctx, "CREATE SCHEMA IF NOT EXISTS "+sp); err != nil {
			db.Close()
			return nil, fmt.Errorf("create schema %s: %w", sp, err)
		}
	}
	return db, nil
}

// MigratePostgres applies db/migrations-postgres.
func MigratePostgres(ctx context.Context, db *sql.DB) error {
	gooseMu.Lock()
	defer gooseMu.Unlock()
	goose.SetBaseFS(dbfiles.MigrationsPostgres)
	goose.SetLogger(goose.NopLogger())
	if err := goose.SetDialect("postgres"); err != nil {
		return err
	}
	if err := goose.UpContext(ctx, db, "migrations-postgres"); err != nil {
		return fmt.Errorf("migrate: %w", err)
	}
	return nil
}

// IsPostgres reports whether db was opened by OpenPostgres.
func IsPostgres(db *sql.DB) bool {
	_, ok := db.Driver().(pgDriver)
	return ok
}

// RetryableTx reports a PostgreSQL serialization failure or deadlock: the transaction can be run again.
// 25P02 (the transaction was aborted by an earlier error) counts too: application code that tolerates a
// failed read inside a transaction (SQLite lets the transaction go on) leaves PostgreSQL's transaction
// aborted, and under SERIALIZABLE that earlier error is a serialization failure. A deterministic error
// would fail every attempt and surface after txAttempts.
func RetryableTx(err error) bool {
	var pe *pgconn.PgError
	return errors.As(err, &pe) && (pe.Code == "40001" || pe.Code == "40P01" || pe.Code == "25P02")
}

// UniqueViolation reports a unique constraint failure on either database. constraint (a PostgreSQL index
// or constraint name, or the SQLite "table.column, ..." text) narrows it; empty matches any.
func UniqueViolation(err error, pgConstraint, sqliteColumns string) bool {
	var pe *pgconn.PgError
	if errors.As(err, &pe) {
		return pe.Code == "23505" && (pgConstraint == "" || pe.ConstraintName == pgConstraint)
	}
	return err != nil && strings.Contains(err.Error(), "UNIQUE constraint failed") &&
		(sqliteColumns == "" || strings.Contains(err.Error(), sqliteColumns))
}

// ---- the connector and connection that rewrite statements ----

type pgDriver struct{}

func (pgDriver) Open(string) (driver.Conn, error) {
	return nil, errors.New("use store.OpenPostgres")
}

type pgConnector struct{ inner driver.Connector }

func (c *pgConnector) Connect(ctx context.Context) (driver.Conn, error) {
	conn, err := c.inner.Connect(ctx)
	if err != nil {
		return nil, err
	}
	return &pgConn{conn.(*stdlib.Conn)}, nil
}

func (c *pgConnector) Driver() driver.Driver { return pgDriver{} }

type pgConn struct{ *stdlib.Conn }

func (c *pgConn) Prepare(q string) (driver.Stmt, error) { return c.Conn.Prepare(Postgres(q)) }

func (c *pgConn) PrepareContext(ctx context.Context, q string) (driver.Stmt, error) {
	return c.Conn.PrepareContext(ctx, Postgres(q))
}

func (c *pgConn) ExecContext(ctx context.Context, q string, args []driver.NamedValue) (driver.Result, error) {
	if err := noNUL(args); err != nil {
		return nil, err
	}
	return c.Conn.ExecContext(ctx, Postgres(q), args)
}

func (c *pgConn) QueryContext(ctx context.Context, q string, args []driver.NamedValue) (driver.Rows, error) {
	if err := noNUL(args); err != nil {
		return nil, err
	}
	return c.Conn.QueryContext(ctx, Postgres(q), args)
}

// ErrNUL: PostgreSQL text cannot hold a NUL character (SQLite can). The statement is not sent, so the
// transaction stays usable; the API answers 422 instead of failing with a database error.
var ErrNUL = errors.New("text may not contain NUL characters")

func noNUL(args []driver.NamedValue) error {
	for _, a := range args {
		v := a.Value
		if vr, ok := v.(driver.Valuer); ok {
			v, _ = vr.Value()
		}
		if s, ok := v.(string); ok && strings.IndexByte(s, 0) >= 0 {
			return ErrNUL
		}
	}
	return nil
}

// ---- the rewrite ----

var rewritten sync.Map // SQLite text → PostgreSQL text

// Postgres returns the PostgreSQL form of a statement written for SQLite (cached).
func Postgres(q string) string {
	if v, ok := rewritten.Load(q); ok {
		return v.(string)
	}
	out := placeholders(dialect(q))
	rewritten.Store(q, out)
	return out
}

var reSchemaName = regexp.MustCompile(`^[a-z_][a-z0-9_]{0,62}$`)

var (
	reILike        = regexp.MustCompile(`(?i)LIKE (\?\d*) ESCAPE '\\' COLLATE NOCASE`)
	reNoCase       = regexp.MustCompile(`(?i)([\w.]+) COLLATE NOCASE`)
	reInstr        = regexp.MustCompile(`(?i)\binstr\(`)
	reGlob         = regexp.MustCompile(`(?i)([\w.]+) GLOB '([^'*?\[\]]*)\*'`)
	reCastInt      = regexp.MustCompile(`(?i)\bAS INTEGER\)`)
	reOrIgnore     = regexp.MustCompile(`(?i)INSERT OR IGNORE INTO`)
	reBoolSum      = regexp.MustCompile(`(?i)\bSUM\(([^()]*(?:=|<|>)[^()]*)\)`)
	reGroupArray   = regexp.MustCompile(`(?i)json_group_array\(([^()]*)\)`)
	reBlobAsText   = regexp.MustCompile(`(?i)CAST\(response_body AS TEXT\)`)
	rePragma       = regexp.MustCompile(`(?i)^\s*PRAGMA\b`)
	reGooseApplied = regexp.MustCompile(`(?i)\bis_applied = 1\b`)
)

// dialect rewrites the SQLite-only constructs the application uses. Each rule is narrow on purpose;
// TestPostgresRewrite pins them.
func dialect(q string) string {
	if rePragma.MatchString(q) {
		return "SELECT 1" // planner hints (PRAGMA optimize): PostgreSQL's autovacuum analyzes on its own
	}
	q = reILike.ReplaceAllString(q, "ILIKE $1 ESCAPE '\\'")
	q = reNoCase.ReplaceAllString(q, "lower($1)")
	q = reInstr.ReplaceAllString(q, "strpos(")
	q = reGlob.ReplaceAllString(q, "starts_with($1, '$2')")
	q = reCastInt.ReplaceAllString(q, "AS BIGINT)")
	q = reBoolSum.ReplaceAllString(q, "SUM(CASE WHEN $1 THEN 1 ELSE 0 END)")
	q = reGroupArray.ReplaceAllString(q, "COALESCE(json_agg($1), '[]'::json)")
	q = reBlobAsText.ReplaceAllString(q, "convert_from(response_body, 'UTF8')")
	q = jsonEach(q)
	q = reGooseApplied.ReplaceAllString(q, "is_applied") // goose's column is boolean on PostgreSQL
	if reOrIgnore.MatchString(q) {
		q = reOrIgnore.ReplaceAllString(q, "INSERT INTO")
		q = strings.TrimRight(strings.TrimSpace(q), ";") + " ON CONFLICT DO NOTHING"
	}
	return q
}

// jsonEach turns json_each(X) into json_array_elements_text(CAST(X AS json)): both yield a `value`
// column per array element (the application only uses arrays of strings).
func jsonEach(q string) string {
	const fn = "json_each("
	for {
		i := strings.Index(strings.ToLower(q), fn)
		if i < 0 {
			return q
		}
		depth, j := 1, i+len(fn)
		for ; j < len(q) && depth > 0; j++ {
			switch q[j] {
			case '(':
				depth++
			case ')':
				depth--
			}
		}
		arg := q[i+len(fn) : j-1]
		q = q[:i] + "json_array_elements_text(CAST(" + arg + " AS json))" + q[j:]
	}
}

// placeholders rewrites ? and ?N to $N outside string literals, quoted identifiers and comments.
func placeholders(q string) string {
	var b strings.Builder
	b.Grow(len(q) + 16)
	n := 0
	for i := 0; i < len(q); i++ {
		c := q[i]
		switch {
		case c == '\'' || c == '"':
			j := i + 1
			for j < len(q) {
				if q[j] == c {
					if j+1 < len(q) && q[j+1] == c { // doubled quote inside the literal
						j += 2
						continue
					}
					break
				}
				j++
			}
			b.WriteString(q[i:min(j+1, len(q))])
			i = j
		case c == '-' && i+1 < len(q) && q[i+1] == '-':
			j := strings.IndexByte(q[i:], '\n')
			if j < 0 {
				j = len(q) - i
			}
			b.WriteString(q[i : i+j])
			i += j - 1
		case c == '/' && i+1 < len(q) && q[i+1] == '*':
			j := strings.Index(q[i+2:], "*/")
			end := len(q)
			if j >= 0 {
				end = i + 2 + j + 2
			}
			b.WriteString(q[i:end])
			i = end - 1
		case c == '?':
			j := i + 1
			for j < len(q) && q[j] >= '0' && q[j] <= '9' {
				j++
			}
			if j > i+1 {
				b.WriteString("$" + q[i+1:j])
			} else {
				n++
				b.WriteString("$" + strconv.Itoa(n))
			}
			i = j - 1
		default:
			b.WriteByte(c)
		}
	}
	return b.String()
}
